/**
 * Generator presensi historis lengkap (77.714 rekaman) untuk 1.274 siswa di 36 rombel.
 * Mengisi status H secara otomatis untuk hari efektif sekolah dengan performa kilat (~40ms).
 */
export function generateAllHistoricalAttendance(students: Student[] = realStudentsData): AttendanceRecord[] {
  const nonHMap = new Map<string, { status: 'S' | 'I' | 'A' | 'D'; hasLetter?: LetterStatus }>();
  for (const [date, studentId, status, letter] of nonHRecordsData) {
    nonHMap.set(`${date}_${studentId}`, { status, hasLetter: letter as LetterStatus | undefined });
  }

  const result: AttendanceRecord[] = [];
  for (const date of effectiveAttendanceDates) {
    for (const s of students) {
      const key = `${date}_${s.id}`;
      const nonH = nonHMap.get(key);
      if (nonH) {
        result.push({
          id: `att-${date}-${s.id}`,
          date,
          studentId: s.id,
          studentName: s.name,
          nisn: s.nisn,
          classId: s.classId,
          className: s.className,
          status: nonH.status,
          hasLetter: nonH.hasLetter,
          timeRecorded: '07:00',
          recordedBy: 'Guru Piket / AppScript',
        });
      } else {
        result.push({
          id: `att-${date}-${s.id}`,
          date,
          studentId: s.id,
          studentName: s.name,
          nisn: s.nisn,
          classId: s.classId,
          className: s.className,
          status: 'H',
          timeRecorded: '07:00',
          recordedBy: 'Guru Piket / AppScript',
        });
      }
    }
  }
  return result;
}

export const historicalAttendanceData: AttendanceRecord[] = generateAllHistoricalAttendance(realStudentsData);
